function spiralOrder(grid) {
  const rows = grid.length, cols = grid[0].length //@init
  const dr = [0, 1, 0, -1], dc = [1, 0, -1, 0] // right, down, left, up
  const seen = grid.map(row => row.map(() => false))
  const out = []
  let r = 0, c = 0, d = 0
  for (let step = 0; step < rows * cols; step++) {
    out.push(grid[r][c]); seen[r][c] = true //@take
    const nr = r + dr[d], nc = c + dc[d] //@next
    if (nr < 0 || nr >= rows || nc < 0 || nc >= cols || seen[nr][nc]) d = (d + 1) % 4 //@turn
    r += dr[d]; c += dc[d] //@move
  }
  return out //@done
}

