function diagonalZigzag(grid) {
  const rows = grid.length
  const cols = grid[0].length
  const out = []
  for (let d = 0; d < rows + cols - 1; d++) {
    const cells = []
    for (let r = Math.max(0, d - cols + 1); r < Math.min(rows, d + 1); r++) cells.push([r, d - r])
    cells.reverse()
    for (const [r, c] of cells) out.push(grid[r][c])
  }
  return out
}

